package com.bodylog.personal;
import android.app.*;import android.appwidget.*;import android.content.*;import android.graphics.*;import android.widget.*;import org.json.*;import java.util.*;import java.time.*;
public class WeightWidgetProvider extends AppWidgetProvider{
 static final String PREFS="bodylog_widget",DATA="weights_state";
 public static void refreshAll(Context c){AppWidgetManager m=AppWidgetManager.getInstance(c);onUpdateAll(c,m,m.getAppWidgetIds(new ComponentName(c,WeightWidgetProvider.class)));}
 private static void onUpdateAll(Context c,AppWidgetManager m,int[] ids){for(int id:ids)draw(c,m,id);}
 @Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){onUpdateAll(c,m,ids);}
 static class Point{LocalDate day;double kg;Point(LocalDate d,double k){day=d;kg=k;}}
 static ArrayList<Point> get(Context c){ArrayList<Point> points=new ArrayList<>();try{JSONObject root=new JSONObject(c.getSharedPreferences(PREFS,0).getString(DATA,"{}"));if(root.optBoolean("demo"))return points;JSONArray a=root.optJSONArray("weights");if(a==null)return points;for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;LocalDate d=LocalDate.parse(o.optString("date"));double kg=o.optDouble("weight",0);if(kg>=20&&kg<=350&&!d.isAfter(LocalDate.now()))points.add(new Point(d,kg));}}catch(Exception ignored){}points.sort((a,b)->a.day.compareTo(b.day));return points;}
 static void draw(Context c,AppWidgetManager m,int id){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget_weight);ArrayList<Point> a=get(c);ArrayList<Point> last7=new ArrayList<>();for(Point p:a)if(!p.day.isBefore(LocalDate.now().minusDays(6)))last7.add(p);
 if(!a.isEmpty()){v.setTextViewText(R.id.widget_weight,String.format(Locale.KOREA,"%.1f kg",a.get(a.size()-1).kg));if(last7.size()>1){double delta=last7.get(last7.size()-1).kg-last7.get(0).kg;v.setTextViewText(R.id.widget_delta,String.format(Locale.KOREA,"최근 7일 %+.1f kg",delta));v.setTextColor(R.id.widget_delta,delta<0?0xff168c68:0xffc36565);}else v.setTextViewText(R.id.widget_delta,"7일 기록이 더 필요해요");}else{v.setTextViewText(R.id.widget_weight,"— kg");v.setTextViewText(R.id.widget_delta,"앱에서 체중을 기록해 주세요");}
 Bitmap img=Bitmap.createBitmap(420,155,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(img);Paint paint=new Paint(3);paint.setStrokeWidth(3);paint.setColor(0xffe6e8f1);for(int k=0;k<3;k++)canvas.drawLine(0,20+55*k,420,20+55*k,paint);if(!last7.isEmpty()){double lo=Double.POSITIVE_INFINITY,hi=Double.NEGATIVE_INFINITY;for(Point p:last7){lo=Math.min(lo,p.kg);hi=Math.max(hi,p.kg);}lo-=.5;hi+=.5;paint.setStrokeWidth(5);paint.setColor(0xff6466ef);Path path=new Path();for(int k=0;k<last7.size();k++){Point p=last7.get(k);float x=10+(float)(p.day.toEpochDay()-LocalDate.now().minusDays(6).toEpochDay())*400/6f;float y=10+(float)((hi-p.kg)/(hi-lo))*130;if(k==0)path.moveTo(x,y);else path.lineTo(x,y);}canvas.drawPath(path,paint);}
 v.setImageViewBitmap(R.id.widget_chart,img);Intent open=new Intent(c,MainActivity.class);v.setOnClickPendingIntent(R.id.widget_root,PendingIntent.getActivity(c,0,open,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT));m.updateAppWidget(id,v);}
}